__wsum
csum_partial(const void *buff, int len, __wsum wsum)
{
    unsigned int sum = (unsigned int)wsum;
    unsigned int result = do_csum(buff, len);

    /* add in old sum, and carry.. */
    result += sum;
    if (sum > result)
